package com.hbm.client.excavator;
import com.hbm.conveyor.MovingItem;import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.MultiBufferSource;import net.minecraft.client.renderer.entity.*;import net.minecraft.client.renderer.texture.OverlayTexture;import net.minecraft.client.renderer.texture.TextureAtlas;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.*;
/** Original stable per-entity small vertical offset and flat/bulk item orientation without bob or spin. */
public final class MovingItemRenderer extends EntityRenderer<MovingItem> {
 public MovingItemRenderer(EntityRendererProvider.Context context){super(context);shadowRadius=0;}
 @Override public void render(MovingItem entity,float yaw,float partial,PoseStack p,MultiBufferSource buffers,int light){p.pushPose();p.translate(0,new java.util.Random(entity.getId()).nextDouble()*.0625,0);var stack=entity.getItemStack();var renderer=Minecraft.getInstance().getItemRenderer();var model=renderer.getModel(stack,entity.level(),null,entity.getId());if(!model.isGui3d()){p.mulPose(Axis.XP.rotationDegrees(90));p.translate(0,-.1875,0);if(!Minecraft.useFancyGraphics())p.mulPose(Axis.YP.rotationDegrees(180));}frame(entity,stack,model,p,buffers,light);p.popPose();}
 /** Source RenderItem.renderInFrame: original miniature counts/spacing and no display-transform approximations. */
 private static void frame(MovingItem entity,ItemStack stack,net.minecraft.client.resources.model.BakedModel model,PoseStack p,MultiBufferSource buffers,int light){renderSourceFrame(entity,stack,model,p,buffers,light);}
 public static void renderSourceFrame(net.minecraft.world.entity.Entity entity,ItemStack stack,net.minecraft.client.resources.model.BakedModel model,PoseStack p,MultiBufferSource buffers,int light){var renderer=Minecraft.getInstance().getItemRenderer();if(model.isCustomRenderer()){renderer.renderStatic(stack,ItemDisplayContext.GROUND,light,OverlayTexture.NO_OVERLAY,p,buffers,entity.level(),entity.getId());return;}p.translate(0,.1,0);int amount=stack.getCount();boolean fancy=Minecraft.useFancyGraphics();if(model.isGui3d()){p.scale(1.25F,1.25F,1.25F);p.translate(0,.05,0);p.mulPose(Axis.YP.rotationDegrees(-90));p.scale(.25F,.25F,.25F);int count=amount>40?5:amount>20?4:amount>5?3:amount>1?2:1;var random=new java.util.Random(187);for(int i=0;i<count;i++){p.pushPose();if(i>0)p.translate((random.nextFloat()*2-1)*.2F/.25F,(random.nextFloat()*2-1)*.2F/.25F,(random.nextFloat()*2-1)*.2F/.25F);renderer.renderStatic(stack,ItemDisplayContext.NONE,light,OverlayTexture.NO_OVERLAY,p,buffers,entity.level(),0);p.popPose();}}else{p.scale(.5128205F,.5128205F,.5128205F);p.translate(0,-.05,0);p.mulPose(Axis.YP.rotationDegrees(180));int count=fancy?(amount<2?1:amount<16?2:amount<32?3:4):(amount>40?5:amount>20?4:amount>5?3:amount>1?2:1);var random=new java.util.Random(187);for(int i=0;i<count;i++){p.pushPose();if(fancy)p.translate(0,.25,-(.0625F+.021875F)*count/2+(.0625F+.021875F)*(i+1)-.03125);else{p.translate(0,.25,0);if(i>0)p.translate((random.nextFloat()*2-1)*.3F,(random.nextFloat()*2-1)*.3F,(random.nextFloat()*2-1)*.3F);}renderer.renderStatic(stack,ItemDisplayContext.NONE,light,OverlayTexture.NO_OVERLAY,p,buffers,entity.level(),0);p.popPose();}}}
 @Override public ResourceLocation getTextureLocation(MovingItem entity){return TextureAtlas.LOCATION_BLOCKS;}
}
